import { inject } from '@angular/core';
import { CanActivateFn } from '@angular/router';
import { AuthService } from '../services/auth.service';

/**
 * Functional route guard — blocks navigation to protected routes
 * if no valid authentication signal is present.
 * Redirects the user back to the main WifakBankProject portal.
 */
export const authGuard: CanActivateFn = (_route, _state) => {
  const authService = inject(AuthService);

  if (authService.isAuthenticated()) {
    return true;
  }

  // No valid session — send user back to main portal login
  window.location.href = 'http://localhost:4200/login';
  return false;
};
